// rt_sigreturn() is invoked by the signal trampoline (assembly stub)
// after a signal handler returns. It is not called by user code.

// The kernel saves necessary state into this structure
typedef struct ucontext {
    struct ucontext *uc_link;
    stack_t          uc_stack;
    mcontext_t       uc_mcontext; // Saved CPU registers/context
    sigset_t         uc_sigmask;  // Saved signal mask
    // ...
} ucontext_t;

// Setup requiring ucontext_t for restoration
struct sigaction sa = { .sa_flags = SA_SIGINFO };
